.view-gallery-live-actions{display:flex;align-items:center;gap:1rem;flex:none}.view-gallery-live-actions a{color:inherit;font:500 .76rem/1.4 "Quattrocento Sans",sans-serif;text-decoration:underline;text-decoration-color:color-mix(in srgb,currentColor 35%,transparent);text-underline-offset:5px}.view-gallery-live-actions a span{display:inline-block;margin-left:.25rem;transition:transform 180ms cubic-bezier(.23,1,.32,1)}
.view-gallery-live-transport{display:grid;place-items:center;width:2rem;height:2rem;padding:0;border:0;border-radius:50%;background:none;color:var(--site-text-secondary);cursor:var(--site-interactive-cursor);transition:background 180ms ease,color 180ms ease}.view-gallery-live-transport svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.25;stroke-linecap:round;stroke-linejoin:round}
@keyframes view-gallery-pulse{0%,100%{opacity:.25;transform:translateY(0)}50%{opacity:.9;transform:translateY(-3px)}}
@media(hover:hover) and (pointer:fine){.view-gallery-live-modes button:hover{color:var(--site-text-primary)}.view-gallery-live-actions a:hover span{transform:translate(3px,-3px)}.view-gallery-live-transport:hover{background:color-mix(in srgb,currentColor 9%,transparent);color:var(--site-text-primary)}}
@media(max-width:700px){.view-gallery-live-stage figcaption{align-items:center}.view-gallery-live-modes{width:100%;gap:.7rem}.view-gallery-live-modes button{min-width:0;flex:1}.view-gallery-live-modes small{display:none}.view-gallery-live-actions a{display:none}}
@media(prefers-reduced-motion:reduce){.view-gallery-live-loading span{animation:none}.view-gallery-live-modes button,.view-gallery-live-modes button::after,.view-gallery-live-actions a span{transition:none}}
</style>
