<template>
    <div>
      <h1 data-scroll-reveal>
        Website Traffic
      </h1>
      <article data-scroll-group data-scroll-step="110">
        <p>This page shows how visitors move through the site, including which pages they open and how activity changes over time.</p>
        <p>Activity appears in aggregate. Individual visitors are not identified.</p>
        <div ref="trafficReport" class="trafficReport" data-scroll-reveal></div>
      </article>
    </div>
  </template>

<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';

export default {
  name: 'TrafficTab',
  mixins: [scrollRevealMixin],
  data() {
      return {
          cleanupReport: null,
          reportDisposed: false,
      };
  },
  async mounted() {
      const { initScript } = await import('../assets/js/loadtrafficreport.js');
      if (this.reportDisposed) return;
      this.cleanupReport = initScript(this.$refs.trafficReport);
  },
  beforeUnmount() {
      this.reportDisposed = true;
      this.cleanupReport?.();
      this.cleanupReport = null;
  },
}
</script>
